						events: [],
						page: input.page,
						pageCount: undefined,
						since: input.since,
						expected404Outcome: "end_of_list" as const,
					}),
			),
		);
	});

	const operation: WorkoutsEventsOperation = {
		descriptor: workoutsEventsDescriptor,
		effect,
		execute(input, options) {
			return Effect.runPromise(operation.effect(input, options));
		},
	};
	return operation;
