				lazyRequestEffectClient,
			),
			update: createWorkoutsUpdateOperation(lazyRequestEffectClient),
		},
		bodyMeasurements: {
			list: createBodyMeasurementsListOperation(lazyRequestEffectClient),
		},
	};
}

